    printf("\n所有排列 res = \n");
    for (int i = 0; i < returnSize; i++) {
        printArray(res[i], numsSize);
    }

    // 释放内存
    for (int i = 0; i < returnSize; i++) {
        free(res[i]);
    }
    free(res);

